// 为每一行商品构建多语言 Amazon Listing + SEO 博客提示词
const items = $input.all();
const results = [];
for (const item of items) {
  const d = item.json;
  results.push({
    json: {
      sku: d.sku || d['SKU'] || '',
      name: d.name || d['商品名称'] || '',
      category: d.category || d['类目'] || '',
      desc: d.desc || d['中文描述'] || '',
      country: d.country || d['目标国家'] || 'US',
      prompt: `请为以下商品生成亚马逊多语言 Listing（英文主 Listing + 德语/法语/日语/西语版本）以及 1200 词 SEO 博客文案。\n\n商品名称：${d.name || d['商品名称'] || ''}\n类目：${d.category || d['类目'] || ''}\n中文描述：${d.desc || d['中文描述'] || ''}\n目标站点：${d.country || d['目标国家'] || 'US'}\n\n要求：标题不超过 200 字符、五点卖点、产品描述、后台搜索关键词；SEO 博客含 H1/H2 结构、关键词布局与 FAQ。全部用 JSON 输出。`
    }
  });
}
return results;

