// 解析 OpenAI 兼容返回，取出正文并转为结构化字段
const items = $input.all();
const results = [];
for (const item of items) {
  const body = item.json;
  const content = body?.choices?.[0]?.message?.content || body?.output_text || JSON.stringify(body);
  let parsed = null;
  try {
    parsed = JSON.parse(content);
  } catch (e) {
    parsed = { raw: content };
  }
  results.push({ json: { ...item.json, ...parsed, rawContent: content } });
}
return results;
